def solve(grid):
    rows, cols = len(grid), len(grid[0])
    # Find connected components of 0s
    visited = [[False]*cols for _ in range(rows)]
    components = []

    def bfs(r, c):
        from collections import deque
        q = deque([(r, c)])
        visited[r][c] = True
        cells = []
        while q:
            x, y = q.popleft()
            cells.append((x, y))
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny] == 0:
                    visited[nx][ny] = True
                    q.append((nx, ny))
        return cells

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                components.append(bfs(r, c))

    largest = max(components, key=len) if components else []
    largest_set = set(largest)

    result = [row[:] for row in grid]
    for r, c in largest_set:
        result[r][c] = 1
    return result
